function newDesign(product){const vehicle=!!product.views;return {productId:product.id,options:{sizeIndex:0,orientation:LANDSCAPE.includes(product.id)||vehicle||product.group==='Apparel'&&product.sizes[0].width>product.sizes[0].height?'landscape':'portrait',quantity:product.quantity[0],rounded:false,fold:product.folds[0]||'',sideCount:vehicle?product.views.length:product.group==='Apparel'?4:product.twoSided?2:1,values:Object.fromEntries(product.options.map(o=>[o.key,o.options[0].value])),selections:{},coupon:'',...(vehicle?{vehicleModel:product.vehicleModels?.[0]||'',vehicleColour:'white',...(product.bodies?{vehicleBody:product.defaultBody||product.bodies[0].id}:{})}:{})},sides:Array.from({length:sideSlots(product)},()=>({background:'#ffffff',layers:[]})),assets:[],notes:''};}
// Older saved designs predate per-view vehicle sides; pad them so every view can be edited.
function normalise(design,product){while(design.sides.length<sideSlots(product))design.sides.push({background:product.views?paintHex(design.options):'#ffffff',layers:[]});if(product.views)design.options.sideCount=product.views.length;return design;}
// Vehicles: an artboard background that is just the vehicle's paint is not printed (and the mockup repaints the body instead).
function artworkSVG(model,i,urls,fonts,bleed){const svg=svgArtwork(model,i,urls,fonts,bleed),p=PRODUCTS.find(p=>p.id===model.productId),bg=model.sides[i]?.background||'';if(!p?.views||bg.toLowerCase()!==paintHex(model.options))return svg;return svg.replace(`fill="${bg}"/>`,'fill="none"/>');}
const dataURL=blob=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});

