const WEBKIT=typeof navigator!=='undefined'&&/AppleWebKit/.test(navigator.userAgent)&&(!/(Chrome|Chromium|Edg|OPR)\//.test(navigator.userAgent)||/iP(hone|ad|od)/.test(navigator.userAgent));
async function svgImage(text){const srcs=[...new Set([...text.matchAll(/href="(data:image\/[^"]+)"/g)].map(m=>m[1]))];await Promise.all(srcs.map(async u=>{try{const i=await loadImage(u.replace(/&amp;/g,'&'));await i.decode?.();}catch{}}));const img=await loadImage('data:image/svg+xml;charset=utf-8,'+encodeURIComponent(text));try{await img.decode?.();}catch{}return img;}
