 function ask(title,text,choices){const dialog=$('[data-confirm-dialog]');dialog.innerHTML=`<form method="dialog"><h2>${esc(t(title))}</h2><p>${esc(t(text))}</p><div class="studio-dialog-actions">${choices.map(([value,label,kind])=>`<button class="studio-action ${kind||''}" value="${value}">${esc(t(label))}</button>`).join('')}</div></form>`;return new Promise(resolve=>{dialog.returnValue='cancel';dialog.addEventListener('close',()=>resolve(dialog.returnValue||'cancel'),{once:true});dialog.showModal();dialog.querySelector('.primary')?.focus();});}
 async function beforeLeave(){if(!hasContent()||change===savedChange&&storedOnServer)return true;status('Saving your design…');try{await withTimeout(save(),6000);return true;}catch(e){status(e.message,true);return await ask('Your design was not saved','Leave this design anyway? Unsaved changes will be lost.',[['leave','Leave without saving','primary'],['cancel','Stay here']])==='leave';}}

