 function productCardHTML(){const card=apparel()?apparelCardFor(product):null,img=apparel()?garmentPhoto(product.id,design.options.values.colour||0):product.views?vehicleThumb():product.thumb||'/satin/img/'+product.photo+'-480.webp';return `<div class="studio-product-card cv-product-card"><img src="${img}" alt="" data-product-thumb><div><b data-no-translate>${esc(apparel()?(card?t(card.name):product.name):t(product.name))}</b><span>${apparel()?esc(product.garment.name.split('|').pop().trim()):esc(t(product.group))}</span><a href="${localizedPath('/satin/design-studio')}" data-change-product>Change product</a></div></div>`;}
