 async function startNew(){const choice=hasContent()?await ask('Start a new design?','Do you want to save your current design before starting a new one?',[['save','Save','primary'],['discard','Don’t save'],['cancel','Cancel']]):'discard';if(choice==='cancel')return;if(choice==='save'){await save();await loadSaved();}clearTimeout(saveTimer);designId=crypto.randomUUID();storedOnServer=false;{const vb=design.options.vehicleBody,vm=design.options.vehicleModel;design=newDesign(product);if(vb){design.options.vehicleBody=vb;design.options.vehicleModel=vm;}}resetState();const url=new URL(location.href);url.searchParams.delete('designId');window.history.replaceState(window.history.state,'',url.pathname+url.search);markup();await refreshRule();renderStage();renderLayers();renderPages();status(choice==='save'?'Design saved. New blank design ready.':'New blank design ready.');}
 async function switchGarment(id){const next=PRODUCTS.find(p=>p.id===id&&p.group==='Apparel');if(!next||next.id===product.id)return;snapshot();product=next;design.productId=next.id;design.options.values={};design.options.selections={};normalise(design,product);selected=null;side=0;const url=new URL(location.href);url.searchParams.set('product',id);window.history.replaceState(window.history.state,'',url.pathname+url.search);markup();await refreshRule();changed();renderStage();}

 /* ---------- save to the customer account (My account → Saved designs) ---------- */
 async function customer(){try{const r=await fetch('/api/customer/me',{credentials:'same-origin'});const v=await r.json();return r.ok&&v.customer?v:null;}catch{return null;}}
 // Small front/back mockup kept with the saved design (thumbnail + PNG download in My account).
 async function quickMockup(){const model=structuredClone(design),arts=await artsFor(model,1400);if(apparel())return renderMockup(model,arts,{photoFor:k=>photoFor(k,model),background:'#f1f2f4'});if(vehicle())return renderMockup(model,arts,{});return (await mockupFor(model)).mockup;}
 async function accountSave(){await save();await loadSaved();const me=await customer();
  if(!me){const choice=await ask('Save this design to your account','Sign in or create a free account to keep this design in My account → Saved designs. You can download it, edit it and order it any time. It also stays in this browser for 30 days.',[['login','Sign in','primary'],['signup','Create account'],['local','Keep in this browser only']]);
   if(choice==='login'||choice==='signup'){const back=location.pathname+'?'+new URLSearchParams({product:product.id,designId,account:'save'});location.assign(localizedPath(choice==='login'?'/satin/login':'/satin/register')+'?return='+encodeURIComponent(back));return;}
   if(choice==='local')status('Saved in this browser for 30 days.');return;}
  setBusy(true);status('Saving to your account…');try{let thumb='';try{thumb=await compact(await quickMockup(),3500000);}catch(e){console.warn('Mockup thumbnail failed',e);}
   const r=await fetch('/api/customer/designs/save',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':me.csrf},body:JSON.stringify({id:designId,thumb})}),v=await r.json().catch(()=>({}));if(!r.ok)throw Error(v.error||'Could not save to your account.');
   status('Saved to your account (My account → Saved designs).');}finally{setBusy(false);}}

 /* ---------- rendering for mockups and print files ---------- */
 async function pngFor(model,index,max=4096,fonts=''){const p=PRODUCTS.find(p=>p.id===model.productId),text=artworkSVG(model,index,embedded,fonts,false),d=dimensions(p,model.options,index),longest=Math.max(d.width,d.height),dpi=Math.min(300,max/longest);const img=await svgImage(text);const c=document.createElement('canvas');c.width=Math.max(1,Math.round(d.width*dpi));c.height=Math.max(1,Math.round(d.height*dpi));const ctx=c.getContext('2d');const ls=labelShape(p,model.options);if(ls==='ellipse'){ctx.beginPath();ctx.ellipse(c.width/2,c.height/2,c.width/2,c.height/2,0,0,Math.PI*2);ctx.clip();}else if(ls==='round'){ctx.beginPath();ctx.roundRect(0,0,c.width,c.height,Math.min(c.width,c.height)*.12);ctx.clip();}else if(model.options.rounded&&p.rounded){ctx.beginPath();ctx.roundRect(0,0,c.width,c.height,Math.min(c.width,c.height)*.06);ctx.clip();}await paintSVG(ctx,img,c.width,c.height);return c;}
 function activeSides(model){const p=PRODUCTS.find(p=>p.id===model.productId),v=sideViews(p);if(p.views)return v.map((_,i)=>i);if(p.group==='Apparel'){const printed=v.map((_,i)=>i).filter(i=>model.sides[i]?.layers.length);return printed.length?printed:[0];}return v.map((_,i)=>i).filter(i=>i<model.options.sideCount);}
 // Uploads cap PNG data URLs at 4 MB; scale down until the encoded image fits comfortably.
 async function compact(url,limit=3600000){let out=url;for(let i=0;i<6&&out.length>limit;i++){const img=await loadImage(out),c=document.createElement('canvas');c.width=Math.round(img.width*.8);c.height=Math.round(img.height*.8);c.getContext('2d').drawImage(img,0,0,c.width,c.height);out=c.toDataURL('image/png');}return out;}
 async function artsFor(model,max){const fonts=await fontCSSFor(model),arts=[];for(const i of activeSides(model))arts[i]=await pngFor(model,i,max,fonts);return arts;}
 async function mockupFor(model){const sides=activeSides(model),arts=await artsFor(model,product.views?2400:3000);const shown=sides.map(i=>arts[i]),h=Math.min(900,...shown.map(a=>a.height)),widths=shown.map(a=>a.width*h/a.height),total=widths.reduce((a,b)=>a+b,0)+40*(shown.length-1),scale=Math.min(1,1800/total);const c=document.createElement('canvas');c.width=Math.round(total*scale);c.height=Math.round(h*scale);const g=c.getContext('2d');let x=0;shown.forEach((a,i)=>{if(product.views){g.fillStyle=model.sides[sides[i]]?.background||'#ffffff';g.fillRect(x,0,widths[i]*scale,h*scale);}g.drawImage(a,x,0,widths[i]*scale,h*scale);x+=(widths[i]+40)*scale;});
  const opts={photoFor:key=>photoFor(key,model),background:model.options.mockupBackground||'#f1f2f4',colour:garmentHex()};let shots=[];try{shots=await photoMockups(model,arts,opts);}catch(e){console.warn(e);}const rendered=await renderMockup(model,arts,opts);return {proof:await compact(c.toDataURL('image/png')),mockup:await compact(rendered),shots:shots.map(s=>({label:s.label,url:s.canvas.toDataURL('image/jpeg',.88)}))};}
 // Print payload sent with approval. Keep this shape stable ({artwork:[{side,key,svg}],dimensions});
 // extra per-side data (e.g. PNG rasters) can be added to each artwork entry here.
 async function printRasters(model,fonts,cap=30e6){/* raster of each side at trim + bleed for the shop's print-ready PDF: 300 DPI for small print, up to 150 DPI for large format (viewed from a distance), within the browser's canvas limits */const out=[];let total=0;const ios=/iP(hone|ad|od)/.test(navigator.userAgent)||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1,budget=ios?16e6:32e6,large=product.group==='Large format'||vehicle();
  for(const i of activeSides(model)){const d=dimensions(product,model.options,i),b=Number(d.bleed)||0,W=d.width+2*b,H=d.height+2*b;let dpi=Math.min(large?150:300,Math.sqrt(budget/(W*H)),16000/Math.max(W,H));const img=await svgImage(artworkSVG(model,i,embedded,fonts,true));const png=product.group==='Apparel';let data='',pw=0,ph=0;
   /* print files are CMYK: opaque artwork becomes a CMYK JPEG here; apparel keeps a transparent PNG, converted to CMYK when the PDF is built */for(const k of [1,.75,.55,.4]){const r=dpi*k,c=document.createElement('canvas');c.width=Math.max(1,Math.round(W*r));c.height=Math.max(1,Math.round(H*r));const x=c.getContext('2d',{willReadFrequently:!png});if(!x)continue;await paintSVG(x,img,c.width,c.height,png?'':'#ffffff');let u='';try{u=png?c.toDataURL('image/png'):bytesToDataURL(await canvasToCMYKJpeg(c,90),'image/jpeg');}catch(e){console.warn('print raster',e);}const cw=c.width,ch=c.height;c.width=c.height=1;if(u.length>32&&total+u.length<=cap){data=u;dpi=r;pw=cw;ph=ch;break;}}
   if(!data)continue;total+=data.length;out.push({side:i,key:sideViews(product)[i]?.key||'side-'+(i+1),image:data,widthIn:d.width,heightIn:d.height,bleedIn:b,dpi:Math.round(dpi*100)/100,w:pw,h:ph,...(png?{}:{cmyk:true})});}return out;}
// Print SVGs embed every uploaded image; very large photos are re-encoded (max 4500 px, the original upload is still attached to the order) so the file stays within the server's size limit.
const liteCache={};
async function liteEmbedded(){const out={...embedded};for(const [id,url] of Object.entries(embedded)){if(typeof url!=='string'||url.length<4e6||url.startsWith('data:image/svg'))continue;if(!liteCache[id]){try{const img=await loadImage(url),k=Math.min(1,4500/Math.max(img.naturalWidth||img.width,img.naturalHeight||img.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round((img.naturalWidth||img.width)*k));c.height=Math.max(1,Math.round((img.naturalHeight||img.height)*k));c.getContext('2d').drawImage(img,0,0,c.width,c.height);let d=c.toDataURL('image/webp',.92);if(!d.startsWith('data:image/webp'))d=url.startsWith('data:image/jpeg')?c.toDataURL('image/jpeg',.92):c.toDataURL('image/png');liteCache[id]=d.length<url.length?d:url;}catch{liteCache[id]=url;}}out[id]=liteCache[id];}return out;}
async function printPayload(model){const fonts=await fontCSSFor(model,true),lite=await liteEmbedded();const out={artwork:activeSides(model).map(i=>({side:i,key:sideViews(product)[i]?.key||'side-'+(i+1),svg:artworkSVG(model,i,lite,fonts,true)})),dimensions:dimensions(product,model.options)};try{const blob=await layeredPDF(model,fonts);if(blob.size<=21e6)out.printPdf=await blobDataURL(blob);}catch(e){console.warn('Layered PDF failed',e);}
 try{const cap=out.printPdf?12e6:30e6;out.print=rasterCache.change===change&&rasterCache.id===designId&&rasterCache.cap===cap?rasterCache.data:await printRasters(model,fonts,cap);rasterCache={change,id:designId,data:out.print,cap};}catch(e){console.warn('Print-ready rasters failed',e);}return out;}
 // Layered print pages: background as a vector colour, then every element rendered alone (cropped, transparent) at up to
 // 300 DPI (150 DPI large format / vehicles) so the shop can select, move or recolour text, graphics and mascots separately.
 const printLayerName=(l,n)=>{const kind={text:'Text',image:'Image',clip:'Mascot',shape:'Graphic',rect:'Rectangle',circle:'Circle',line:'Line'}[l.type]||'Element';
  const extra=l.type==='text'?String(l.text).replace(/\s+/g,' ').trim().slice(0,40):l.type==='clip'?(MASCOTS[l.clip]?.label||l.clip):l.type==='shape'?(EXTRA_SHAPE_LABELS?.[l.shape]||l.shape):'';return `${n}. ${kind}${extra?' - '+extra:''}`;};
 async function printLayers(model,fonts,k=1){const ios=/iP(hone|ad|od)/.test(navigator.userAgent)||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1,budget=ios?10e6:22e6,large=product.group==='Large format'||vehicle(),pages=[];let total=0;
  for(const i of activeSides(model)){const d=dimensions(product,model.options,i),b=Number(d.bleed)||0,PW=d.width+2*b,PH=d.height+2*b,sd=model.sides[i];if(!sd)continue;
   let bg=sd.background||'#ffffff';if(product.views&&bg.toLowerCase()===paintHex(model.options))bg=null;if(product.group==='Apparel'&&bg==='#ffffff')bg=null;
   const layers=[];let n=0,rasterized=0;
   for(const l of sd.layers||[]){n++;
    // vector first (shapes, mascots, gradients, outlined text, photos at full resolution); a raster only when that can't be exact
    try{const v=await svgToVector(svgArtwork(model,i,embedded,'',true,{noBackground:true,layers:[l]}),{prefix:`s${i}e${n}_`,maxImage:Math.round(6000*k)});
     layers.push({name:printLayerName(l,n),vec:v});total+=v.ops.length+v.images.reduce((a,x)=>a+x.img.data.length+(x.img.smask?.data.length||0),0);continue;}
    catch(e){if(!(e instanceof VectorError))console.warn('vector layer',e);else console.info('raster layer',n,e.message);rasterized++;}const cx=(l.x+l.w/2)*d.width,cy=(l.y+l.h/2)*d.height,hw=l.w*d.width/2,hh=l.h*d.height/2,r=(l.rotation||0)*Math.PI/180,ex=Math.abs(hw*Math.cos(r))+Math.abs(hh*Math.sin(r)),ey=Math.abs(hw*Math.sin(r))+Math.abs(hh*Math.cos(r));
    const extra=(l.type==='line'?(l.stroke||2)/100:0)+(l.outline||0)/100+.25,txt=l.type==='text',padX=(txt?ex*.08+ey*.6:ex*.12)+extra,padY=(txt?ey*.6:ey*.12)+extra;
    const x0=Math.max(-b,cx-ex-padX),x1=Math.min(d.width+b,cx+ex+padX),y0=Math.max(-b,cy-ey-padY),y1=Math.min(d.height+b,cy+ey+padY);if(x1-x0<=0||y1-y0<=0)continue;
    const bw=x1-x0,bh=y1-y0,dpi=Math.min(large?150:300,Math.sqrt(budget/(bw*bh)),16000/Math.max(bw,bh))*k;
    const img=await svgImage(svgArtwork(model,i,embedded,fonts,true,{noBackground:true,layers:[l]}));
    const c=document.createElement('canvas');c.width=Math.max(1,Math.round(bw*dpi));c.height=Math.max(1,Math.round(bh*dpi));const g=c.getContext('2d',{willReadFrequently:true});if(!g)continue;
    const draw=()=>{g.clearRect(0,0,c.width,c.height);g.drawImage(img,(-b-x0)*dpi,(-b-y0)*dpi,PW*dpi,PH*dpi);};draw();if(WEBKIT){await new Promise(r=>setTimeout(r,250));draw();}
    let res=null;try{res=await layerFromCanvas(c,l.type==='image',/^#[0-9a-f]{6}$/i.test(l.color||'')?l.color:'#ffffff');}catch(e){console.warn('print layer',e);}c.width=c.height=1;if(!res)continue;
    const px=1/dpi;layers.push({name:printLayerName(l,n),xIn:x0+b+res.x*px,yIn:y0+b+res.y*px,wIn:res.img.w*px,hIn:res.img.h*px,img:res.img});total+=res.img.data.length+(res.img.smask?.data.length||0);}
   const ls=labelShape(product,model.options);
   // big artwork (vehicles, large banners) is saved at 1:5 — it is vector, so it enlarges to full size without losing sharpness
   const scale=vehicle()||Math.max(PW,PH)>120?5:1,f1=v=>Math.round(v*100)/100,view=sideViews(product)[i];
   const notes=[(view?.label?view.label+' · ':'')+(scale>1?`SCALE 1:${scale} - print at ${scale*100}% = ${f1(PW)} x ${f1(PH)} in with bleed (trim ${f1(d.width)} x ${f1(d.height)} in)`:`Actual size ${f1(PW)} x ${f1(PH)} in with bleed (trim ${f1(d.width)} x ${f1(d.height)} in)`),
    `Vector artwork, CMYK, text converted to outlines, one layer per element${rasterized?` (${rasterized} element${rasterized>1?'s':''} embedded as high-resolution image${rasterized>1?'s':''})`:''} - Satin Graphic Design Studio`];
   pages.push({side:i,widthIn:d.width,heightIn:d.height,bleedIn:b,background:bg,layers,scale,notes,cut:ls&&ls!=='die'?{shape:ls,radiusIn:ls==='round'?Math.min(d.width,d.height)*.12:0}:null});}
  return {pages,total};}
 // Layered print-ready PDF (Blob), kept under ~21 MB so it can travel with the order; cached until the design changes.
 let layeredCache={change:-1,id:'',blob:null};
 async function layeredPDF(model,fonts){if(layeredCache.change===change&&layeredCache.id===designId&&layeredCache.blob)return layeredCache.blob;
  let res=null;for(const k of [1,.7,.5,.35]){res=await printLayers(model,fonts,k);if(res.total<=21e6)break;}
  if(!res.pages.length)throw Error('The PDF could not be created. Try again.');
  const blob=await pdfFromRasters(res.pages,productName()+' - Satin Graphic Design Studio',pdfExtras(model));layeredCache={change,id:designId,blob};return blob;}
 const blobDataURL=b=>new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=()=>no(r.error);r.readAsDataURL(b);});
 // Colours used on the printed sides (backgrounds, text, shapes, gradient ends) as CMYK swatches, plus the mockup as the PDF's last page.
 function pdfExtras(model){const seen=new Set(),hex=[];const add=c=>{if(typeof c==='string'&&/^#[0-9a-f]{6}$/i.test(c)&&!seen.has(c.toLowerCase())){seen.add(c.toLowerCase());hex.push(c.toLowerCase());}};
  for(const i of activeSides(model)){const sd=model.sides[i];if(!sd)continue;if(sd.background&&sd.background.toLowerCase()!=='#ffffff')add(sd.background);for(const l of sd.layers||[]){if(l.type==='image')continue;add(l.color);if(l.gradient)add(l.gradient.to);}}
  const body=vehicle()?vehicleBody(product,model.options):null,d=dimensions(product,model.options);
  return {swatches:hex.map(cmykSwatch),mockup:mockup?{image:mockup,title:'Mockup - '+productName()+(body?.name&&body.name!==productName()?' - '+body.name:''),lines:[(body?.spec?`Vehicle: ${body.name} (${body.spec.length} x ${body.spec.height} in)`:`Size: ${d.width} x ${d.height} in`),'Design Studio export '+new Date().toLocaleDateString('en-CA')+' - colours are listed in CMYK under each page.']}:null};}
 // Print-ready PDF in the browser: one page per printed side, MediaBox = trim + bleed, TrimBox = trim, 300 DPI rasters.
 let rasterCache={change:-1,id:'',data:null};
 async function downloadPDF(force=false){if(busy)return;if(!force&&(!mockup||!$('[data-approve]').checked)){status('Generate and approve the mockup first.',true);return;}setBusy(true);status('Preparing your print-ready PDF…');try{const model=structuredClone(design);const blob=await layeredPDF(model,await fontCSSFor(model,true)),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=product.id+'-print-ready.pdf';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),4000);status('PDF downloaded.');}catch(e){status(e.message,true);}finally{setBusy(false);}}
 async function generate(){if(busy)return;setBusy(true);status('Generating your artwork mockup…');const shotsEl=$('[data-review-shots]');shotsEl.innerHTML=`<div class="cv-loading">${esc(t('Generating your mockup…'))}</div>`;try{const rendered=await mockupFor(structuredClone(design));proof=rendered.proof;mockup=rendered.mockup;$('[data-mockup]').src=mockup;const list=rendered.shots.length?rendered.shots:[{label:t('Mockup'),url:mockup}];shotsEl.innerHTML=list.map(s=>`<figure><img src="${s.url}" alt="${esc(s.label)}"><figcaption>${esc(t(s.label))}</figcaption></figure>`).join('')+(vehicle()&&rendered.shots.length?`<figure><img src="${mockup}" alt="${esc(t('All vehicle views'))}"><figcaption>${esc(t('All vehicle views'))}</figcaption></figure>`:'');$('[data-mockup-panel]').classList.add('visible');status(views().length>1?'Mockup generated. Review every side before approving.':'Mockup generated. Review the artwork before approving.');}catch(e){shotsEl.innerHTML=`<p class="cv-error">${esc(e.message)}</p>`;status(e.message,true);}finally{setBusy(false);}}
